create table _answer (is_correct boolean not null, id bigint generated by default as identity, question_id bigint, text TEXT not null, primary key (id));
create table _attempt (correct_num integer, incorrect_num integer, result numeric(5,2), total_quest_num integer, ended_at timestamp(6), id bigint generated by default as identity, started_at timestamp(6), taking_id bigint, primary key (id));
create table _class_joining (class_id bigint, id bigint generated by default as identity, joined_at timestamp(6), learner_id bigint, _displayed_name varchar(255), _displayed_phone varchar(255), status varchar(255) check (status in ('PENDING','APPROVED','REJECTED','REMOVED')), primary key (id));
create table _classroom (is_deleted boolean default false not null, is_draft boolean, is_enable boolean not null, require_approval boolean, code varchar(8) not null unique, created_at timestamp(6), created_id bigint, id bigint generated by default as identity, name varchar(64) not null, description varchar(128), imageurl TEXT, primary key (id));
create table _practice (correct_answers integer not null, is_completed boolean, is_random boolean, practice_limit integer, practice_offset integer, total_questions integer not null, category_id bigint, created_at timestamp(6), id bigint generated by default as identity, user_id bigint not null, primary key (id));
create table _practice_detail (is_correct boolean, id bigint generated by default as identity, practice_id bigint not null, question_id bigint not null, selected_text varchar(255), primary key (id), unique (practice_id, question_id));
create table _practice_detail_selected_answers (answer_id bigint not null, practice_detail_id bigint not null);
create table _question (category_id bigint, created_id bigint, id bigint generated by default as identity, approval_status varchar(255) check (approval_status in ('PRIVATE','PENDING','PUBLIC','DELETED')), question_level varchar(255) check (question_level in ('EASY','MEDIUM','HARD')), text TEXT not null, type varchar(255) not null check (type in ('SINGLE_CHOICE','MULTIPLE_CHOICE','FILL_IN_BLANK')), primary key (id));
create table _question_creating (quest_id bigint not null, quiz_id uuid not null);
create table _quiz (is_draft boolean not null, is_enable boolean not null, is_exam boolean not null, category_id bigint, created_at timestamp(6), created_id bigint not null, updated_at timestamp(6), id uuid not null, description varchar(1000), image_url TEXT, title varchar(255), primary key (id));
create table _quiz_assigning (answer_shuffled boolean, duration_in_mins integer, is_deleted boolean default false not null, is_hidden boolean default false not null, max_attempt integer, question_shuffled boolean, show_answer boolean, classroom_id bigint, created_at timestamp(6), due_date timestamp(6), id bigint generated by default as identity, start_date timestamp(6), topic_id bigint, quiz_id uuid, assigned_student_ids TEXT, note varchar(255), primary key (id));
create table _quiz_taking (is_assigned boolean, assigning_id bigint, id bigint generated by default as identity, learner_id bigint, quiz_id uuid, status varchar(255) check (status in ('NOT_STARTED','IN_PROGRESS','COMPLETED','EXPIRED')), primary key (id));
create table _user (is_enable boolean default false not null, is_verified boolean default false not null, created_at timestamp(6), created_id bigint, id bigint generated by default as identity, updated_at timestamp(6), phone varchar(15), email varchar(100) not null unique, avatar_url TEXT, full_name varchar(255) not null, note varchar(255), password varchar(255) not null, role varchar(255) not null check (role in ('ADMIN','TEACHER','STUDENT')), primary key (id));
create table _user_attempt_answer (answer_id bigint, attempt_id bigint, id bigint generated by default as identity, question_id bigint, revision bigint, timestamp timestamp(6), selected_text varchar(255), primary key (id));
create table attempt_violations (attempt_id bigint, occurred_at timestamp(6), violation_type_id bigint, id uuid not null, primary key (id));
create table categories (is_public boolean default false, creator_id bigint, id bigint generated by default as identity, parent_id bigint, name varchar(100) not null, description TEXT, primary key (id));
create table class_topics (is_deleted boolean default false not null, classroom_id bigint, id bigint generated by default as identity, name varchar(255) not null, primary key (id));
create table exam_violation (severity_level int default 1, id bigint generated by default as identity, violation_code varchar(50) not null unique, description TEXT, primary key (id));
create table notifications (is_read boolean not null, created_at timestamp(6), id bigint generated by default as identity, user_id bigint, link varchar(255), message TEXT not null, title varchar(255) not null, type varchar(255) check (type in ('QUESTION_APPROVED','QUESTION_REJECTED','JOIN_REQUEST','JOIN_APPROVED','QUIZ_SUBMITTED','QUIZ_ASSIGNED','JOIN_REJECTED','SYSTEM_ALERT')), primary key (id));
